import assert from'node:assert/strict';import{readFileSync}from'node:fs';import{execFileSync}from'node:child_process';import{createHash}from'node:crypto';
const base='7981740d8fb6a552f8815364dea44a5f0664cff2',live='85191aa8174fb6864e49fa8616d106596443ae50',folder='docs/mobile-dictation-fit-20261101/';
const git=(...a)=>execFileSync('git',a,{maxBuffer:128e6}),sha=b=>createHash('sha256').update(b).digest('hex'),sort=a=>a.sort((a,b)=>a.localeCompare(b)),lines=b=>b.toString().trim().split('\n').filter(Boolean);
const roots=['app','components','hooks','data','lib','public','scripts','db','drizzle','.github','AGENTS.md','PUBLICATIE.md','VORMGEVING-VASTGEZET.md','docs/appearance-floor-20261031','docs/KLINK-DOCENTHANDLEIDING.md','vite.config.ts','next.config.ts','package.json','package-lock.json','wrangler.jsonc'];
export function verifyMobileDictationFitRelease(read=readFileSync){
 const r=JSON.parse(read('docs/klink-owner-release-mobile-dictation-fit-20261101.json'));assert.equal(r.approvedBy,'Nico');assert.equal(r.publicationApproved,true);assert.equal(r.appearanceChangeApproved,true);assert.equal(r.baselineSourceCommit,base);assert.equal(r.liveSourceCommit,live);assert(r.userRequest.includes('zonder scrollen')&&r.userRequest.includes('kleine schermen'));
 git('merge-base','--is-ancestor',live,base);git('merge-base','--is-ancestor',base,'HEAD');
 const changed=sort([...new Set([...lines(git('diff','--name-only',base,'--',...roots)),...lines(git('ls-files','--others','--exclude-standard','--',...roots))])]);assert.deepEqual(changed,sort([...r.changedFiles,'docs/appearance-floor-20261031/floor.json',r.approval]));assert.deepEqual(sort(Object.keys(r.files)),r.changedFiles);for(const f of r.changedFiles)assert.equal(sha(read(f)),r.files[f],f);
 assert.equal(git('diff','--name-only',base,'--','components','hooks','data','lib','public','db','drizzle','.github','package.json','package-lock.json','wrangler.jsonc').length,0,'No player logic, content, audio, progress, routes or dependencies change');
 const before=git('show',base+':app/learner-layout.css').toString(),actual=read('app/learner-layout.css').toString();assert(actual.startsWith(before));const delta=actual.slice(before.length);assert.equal(sha(Buffer.from(delta)),r.cssDeltaSha256);assert(delta.includes('@media (max-width: 820px)')&&delta.includes(':has(.cp-pace-controls):has(.cp-text-entry)'));assert(!delta.includes('font-size')&&!delta.includes('overflow: hidden'),'No smaller text or clipped answers');
 const floor=JSON.parse(read('docs/appearance-floor-20261031/floor.json')),old=JSON.parse(git('show',base+':docs/appearance-floor-20261031/floor.json'));assert.deepEqual({...floor,approvedUpdates:old.approvedUpdates},old);assert.deepEqual(floor.approvedUpdates,[...old.approvedUpdates,r.approval]);const approval=JSON.parse(read(r.approval));assert.equal(approval.userRequest,r.userRequest);assert.deepEqual(approval.files,r.files);
 const browser=JSON.parse(read(folder+'checks.json'));assert.equal(browser.checks.length,438);assert.equal(browser.native.length,2);assert.equal(browser.regression.length,16);assert(browser.regression.every(c=>c.navigationRestored));assert.deepEqual(browser.errors,[]);assert.equal(new Set(browser.checks.map(c=>c.id)).size,65);for(const c of browser.checks)for(const k of['allControlsFullyVisible','touchTargets48','stageFits','atTop','noHorizontalScroll','outerFits','modelFits','oldProgressPreserved'])assert.equal(c[k],true,k);for(const c of browser.native)for(const k of['nativePlayback','space','enter','arrows','inputTyping','touch','progressPreserved'])assert.equal(c[k],true,k);
 const previous=JSON.parse(read(folder+'previous-toolbar.json'));assert.equal(previous.checks.length,80);assert.equal(previous.native.length,2);assert.deepEqual(previous.errors,[]);
 const review=JSON.parse(read(folder+'review.json'));for(const k of['all65Rounds','wholeTaskChecked','contentPreserved','audioPreserved','progressPreserved','keyboard','mobile','desktopAndReadingPreserved','localOnly'])assert.equal(review[k],true,k);
 const backup=JSON.parse(read(folder+'backup.json'));assert(backup.verified&&backup.fullReadback&&backup.zipIntegrity&&backup.driveId);assert.deepEqual(backup.files,r.files);return r;
}
export function readBeforeMobileDictationFit(file,r,read=readFileSync){return r.changedFiles.includes(file)||file==='docs/appearance-floor-20261031/floor.json'?git('show',base+':'+file):read(file);}
